#include <bits/stdc++.h>
using namespace std;

#define ms(s, n) memset(s, n, sizeof(s))
#define FOR(i, a, b) for (int i = (a); i < (b); i++)
#define all(a) (a).begin(), (a).end()
#define pb push_back
#define mp make_pair
typedef long long ll;
typedef vector<int> vi;

inline int bitcount(int x) { return __builtin_popcount(x); }

void fw_transform(int *a, int n, int p, bool inv) {
    for (int len = 1; len < n; len <<= 1) {
        for (int i = 0; i < n; i += (len << 1)) {
            for (int j = 0; j < len; j++) {
                int u = a[i + j], v = a[i + j + len];
                if (!inv) {
                    a[i + j] = (u + v) % p;
                } else {
                    a[i + j] = (u - v + p) % p;
                }
            }
        }
    }
}

vector<int> pow_conv(vector<int> a, int k, int p) {
    int n = (int)a.size();
    if (k == 1) return a;
    if (k % 2 == 1) {
        auto temp = pow_conv(a, k - 1, p);
        vector<int> res(n, 0);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j + i < n; j++) {
                res[i + j] = (res[i + j] + (ll)temp[i] * a[j]) % p;
            }
        }
        return res;
    } else {
        auto half = pow_conv(a, k / 2, p);
        vector<int> res(n, 0);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j + i < n; j++) {
                res[i + j] = (res[i + j] + (ll)half[i] * half[j]) % p;
            }
        }
        return res;
    }
}

vector<int> subset_power(vector<int> a, int k, int p) {
    int n = 1;
    while (n < (int)a.size()) n <<= 1;
    static int fa[20][1 << 20], fc[20][1 << 20];
    for (int i = 0; i < 20; i++) {
        for (int j = 0; j < n; j++) {
            fa[i][j] = (j < (int)a.size()) ? a[j] : 0;
        }
        fw_transform(fa[i], n, p, false);
    }
    for (int i = 0; i < n; i++) {
        vector<int> v(20);
        for (int j = 0; j < 20; j++) v[j] = fa[j][i];
        v = pow_conv(v, k, p);
        for (int j = 0; j < 20; j++) fc[j][i] = v[j];
    }
    for (int i = 0; i < 20; i++) {
        fw_transform(fc[i], n, p, true);
    }
    vector<int> res(n, 0);
    for (int j = 0; j < n; j++) {
        int c = bitcount(j);
        if (c < 20 && j < (int)a.size()) {
            res[j] = fc[c][j];
        }
    }
    return res;
}

const int MAXN = 1e6 + 5;
int n, k, p;
int fac[MAXN], invFac[MAXN];
int f[MAXN];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> k >> p;
    int maskVal = 0;
    for (int i = 0; i < 20; i++) {
        if ((n >> i) & 1) maskVal |= (1 << i);
    }
    for (int i = 0; i <= maskVal; i++) {
        int t = 0;
        for (int j = 0; j < 20; j++) {
            if ((n >> j) & 1) {
                t <<= 1;
                t |= (i >> j) & 1;
            }
        }
        f[t] = i;
    }
    if (n & 1) {
        cout << pow(k, n) % p << "\n";
        return 0;
    }
    fac[0] = 1;
    for (int i = 1; i < MAXN; i++) fac[i] = (ll)fac[i - 1] * i % p;
    invFac[MAXN - 1] = pow(fac[MAXN - 1], p - 2, p);
    for (int i = MAXN - 2; i >= 0; i--) invFac[i] = (ll)invFac[i + 1] * (i + 1) % p;
    vector<int> a(maskVal + 1, 0);
    for (int i = 0; i <= maskVal; i++) a[i] = invFac[f[i]];
    int res = pow(k, n) % p;
    a = subset_power(a, k, p);
    int subtractVal = (ll)a[maskVal] * fac[n] % p;
    res = (res - subtractVal + p) % p;
    cout << res << "\n";
    return 0;
}
